/**
 * @param {string[]} queries
 * @param {string[]} dictionary
 * @return {string[]}
 */
var twoEditWords = function(queries, dictionary) {
    const n = queries[0].length;
    let res = [];

    for (const query of queries) {
        let match = false;

        for (const dict of dictionary) {
            let diff = 0;

            for (let k = 0; k < n; k++) {
                if (query[k] !== dict[k]) {
                    diff++;

                    if (diff > 2) {
                        break;
                    }
                }
            }

            if (diff <= 2) {
                match = true;
                break;
            }
        }

        if (match) {
            res.push(query);
        }
    }

    return res;
};

